package com.concatstudio.onegym.routes

import com.concatstudio.onegym.data.DomainConflictException
import com.concatstudio.onegym.data.DomainNotFoundException
import com.concatstudio.onegym.model.*
import com.concatstudio.onegym.respository.ActivityRepository
import com.concatstudio.onegym.security.AuthorizationService
import com.concatstudio.onegym.security.authenticatedUserId
import io.ktor.http.HttpStatusCode
import io.ktor.server.request.receive
import io.ktor.server.response.respond
import io.ktor.server.routing.*
import org.koin.ktor.ext.inject
import java.time.LocalDate

fun Route.activityRouting() {
    val repository: ActivityRepository by inject(); val authorization: AuthorizationService by inject()
    route("/gyms/{gymId}") {
        get("/activities") { val gym = call.gymId() ?: return@get; val actor = call.authenticatedUserId() ?: return@get call.respond(HttpStatusCode.Unauthorized); val manage = authorization.canManageGym(actor, gym); if (!manage && authorization.gymRole(actor, gym) == null) return@get call.respond(HttpStatusCode.Forbidden); call.respond(repository.list(gym, manage && call.request.queryParameters["includeInactive"] == "true")) }
        post("/activities") { val gym = call.gymId() ?: return@post; val actor = call.authenticatedUserId() ?: return@post call.respond(HttpStatusCode.Unauthorized); if (!authorization.canManageGym(actor, gym)) return@post call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.Created) { repository.create(gym, call.receive()) } }
        put("/activities/{activityId}") { val gym = call.gymId() ?: return@put; val id = call.id("activityId") ?: return@put; val actor = call.authenticatedUserId() ?: return@put call.respond(HttpStatusCode.Unauthorized); if (!authorization.canManageActivity(actor, id)) return@put call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.OK) { repository.update(gym, id, call.receive()) } }
        post("/activities/{activityId}/schedules") { val gym = call.gymId() ?: return@post; val id = call.id("activityId") ?: return@post; val actor = call.authenticatedUserId() ?: return@post call.respond(HttpStatusCode.Unauthorized); if (!authorization.canManageActivity(actor, id)) return@post call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.Created) { repository.createSchedule(gym, id, call.receive()) } }
        get("/activities/{activityId}/schedules") { val gym = call.gymId() ?: return@get; val id = call.id("activityId") ?: return@get; val actor = call.authenticatedUserId() ?: return@get call.respond(HttpStatusCode.Unauthorized); if (authorization.gymRole(actor, gym) == null && !authorization.isSuperAdmin(actor)) return@get call.respond(HttpStatusCode.Forbidden); call.activityResult { repository.listSchedules(gym, id) } }
        put("/activities/{activityId}/schedules/{scheduleId}") { val gym = call.gymId() ?: return@put; val activity = call.id("activityId") ?: return@put; val schedule = call.id("scheduleId") ?: return@put; val actor = call.authenticatedUserId() ?: return@put call.respond(HttpStatusCode.Unauthorized); if (!authorization.canManageActivity(actor, activity)) return@put call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.OK) { repository.updateSchedule(gym, activity, schedule, call.receive()) } }
        delete("/activities/{activityId}/schedules/{scheduleId}") { val gym = call.gymId() ?: return@delete; val activity = call.id("activityId") ?: return@delete; val schedule = call.id("scheduleId") ?: return@delete; val actor = call.authenticatedUserId() ?: return@delete call.respond(HttpStatusCode.Unauthorized); if (!authorization.canManageActivity(actor, activity)) return@delete call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.NoContent) { repository.deleteSchedule(gym, activity, schedule); Unit } }
        get("/activities/{activityId}/groups") { val gym = call.gymId() ?: return@get; val id = call.id("activityId") ?: return@get; val actor = call.authenticatedUserId() ?: return@get call.respond(HttpStatusCode.Unauthorized); if (authorization.gymRole(actor, gym) == null && !authorization.isSuperAdmin(actor)) return@get call.respond(HttpStatusCode.Forbidden); call.activityResult { repository.listGroups(gym, id) } }
        post("/activities/{activityId}/groups") { val gym = call.gymId() ?: return@post; val id = call.id("activityId") ?: return@post; val actor = call.authenticatedUserId() ?: return@post call.respond(HttpStatusCode.Unauthorized); if (!authorization.canManageActivity(actor, id)) return@post call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.Created) { repository.createGroup(gym, id, call.receive()) } }
        put("/activities/{activityId}/groups/{groupId}") { val gym = call.gymId() ?: return@put; val activity = call.id("activityId") ?: return@put; val group = call.id("groupId") ?: return@put; val actor = call.authenticatedUserId() ?: return@put call.respond(HttpStatusCode.Unauthorized); if (!authorization.canManageActivity(actor, activity)) return@put call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.OK) { repository.updateGroup(gym, activity, group, call.receive()) } }
        delete("/activities/{activityId}/groups/{groupId}") { val gym = call.gymId() ?: return@delete; val activity = call.id("activityId") ?: return@delete; val group = call.id("groupId") ?: return@delete; val actor = call.authenticatedUserId() ?: return@delete call.respond(HttpStatusCode.Unauthorized); if (!authorization.canManageActivity(actor, activity)) return@delete call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.NoContent) { repository.archiveGroup(gym, activity, group); Unit } }
        get("/me/activities") { val gym = call.gymId() ?: return@get; val user = call.authenticatedUserId() ?: return@get call.respond(HttpStatusCode.Unauthorized); if (authorization.gymRole(user, gym) == null && !authorization.isSuperAdmin(user)) return@get call.respond(HttpStatusCode.Forbidden); call.activityResult { repository.listMyActivities(gym, user) } }
        delete("/activity-group-memberships/{membershipId}/me") { val gym = call.gymId() ?: return@delete; val membership = call.id("membershipId") ?: return@delete; val user = call.authenticatedUserId() ?: return@delete call.respond(HttpStatusCode.Unauthorized); call.activityResult(HttpStatusCode.NoContent) { repository.leaveGroup(gym, membership, user); Unit } }
        post("/activity-groups/{groupId}/memberships/me") { val gym = call.gymId() ?: return@post; val group = call.id("groupId") ?: return@post; val user = call.authenticatedUserId() ?: return@post call.respond(HttpStatusCode.Unauthorized); if (authorization.gymRole(user, gym) == null && !authorization.isSuperAdmin(user)) return@post call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.Created) { repository.joinOpenGroup(gym, group, user) } }
        post("/activity-groups/{groupId}/join-requests") { val gym = call.gymId() ?: return@post; val group = call.id("groupId") ?: return@post; val user = call.authenticatedUserId() ?: return@post call.respond(HttpStatusCode.Unauthorized); if (authorization.gymRole(user, gym) == null && !authorization.isSuperAdmin(user)) return@post call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.Created) { repository.requestJoin(gym, group, user) } }
        get("/activity-groups/{groupId}/memberships") { val gym = call.gymId() ?: return@get; val group = call.id("groupId") ?: return@get; val actor = call.authenticatedUserId() ?: return@get call.respond(HttpStatusCode.Unauthorized); if (!authorization.canManageGym(actor, gym)) return@get call.respond(HttpStatusCode.Forbidden); call.activityResult { repository.listMemberships(gym, group) } }
        post("/activity-group-memberships/{membershipId}/transfer") { val gym = call.gymId() ?: return@post; val membership = call.id("membershipId") ?: return@post; val actor = call.authenticatedUserId() ?: return@post call.respond(HttpStatusCode.Unauthorized); val request = call.receive<TransferActivityGroupMembershipRequest>(); if (!authorization.canManageGym(actor, gym)) return@post call.respond(HttpStatusCode.Forbidden); val date = request.effectiveFrom?.let { runCatching { LocalDate.parse(it) }.getOrNull() } ?: LocalDate.now(); if (date.isBefore(LocalDate.now())) return@post call.respond(HttpStatusCode.BadRequest); call.activityResult(HttpStatusCode.OK) { repository.transferMembership(gym, membership, request.targetGroupId, date) } }
        post("/activity-group-join-requests/{requestId}/approve") { val gym = call.gymId() ?: return@post; val request = call.id("requestId") ?: return@post; val actor = call.authenticatedUserId() ?: return@post call.respond(HttpStatusCode.Unauthorized); val activity = try { repository.activityIdForJoinRequest(gym, request) } catch (_: DomainNotFoundException) { return@post call.respond(HttpStatusCode.NotFound) }; if (!authorization.canManageActivity(actor, activity)) return@post call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.OK) { repository.approveRequest(gym, request, actor) } }
        get("/activity-occurrences") { val gym = call.gymId() ?: return@get; val actor = call.authenticatedUserId() ?: return@get call.respond(HttpStatusCode.Unauthorized); val manage = authorization.canManageGym(actor, gym); if (!manage && authorization.gymRole(actor, gym) == null) return@get call.respond(HttpStatusCode.Forbidden); val from = call.request.queryParameters["from"]?.let { runCatching { LocalDate.parse(it) }.getOrNull() } ?: return@get call.respond(HttpStatusCode.BadRequest); val to = call.request.queryParameters["to"]?.let { runCatching { LocalDate.parse(it) }.getOrNull() } ?: return@get call.respond(HttpStatusCode.BadRequest); call.activityResult { repository.listOccurrences(gym, from, to, manage && call.request.queryParameters["includeInactive"] == "true") } }
        post("/activity-occurrences/{occurrenceId}/reservations") { val gym = call.gymId() ?: return@post; val occurrence = call.id("occurrenceId") ?: return@post; val user = call.authenticatedUserId() ?: return@post call.respond(HttpStatusCode.Unauthorized); if (authorization.gymRole(user, gym) == null && !authorization.isSuperAdmin(user)) return@post call.respond(HttpStatusCode.Forbidden); call.activityResult(HttpStatusCode.Created) { repository.reserve(gym, occurrence, user) } }
        delete("/activity-occurrences/{occurrenceId}/reservations/me") { val gym = call.gymId() ?: return@delete; val occurrence = call.id("occurrenceId") ?: return@delete; val user = call.authenticatedUserId() ?: return@delete call.respond(HttpStatusCode.Unauthorized); call.activityResult(HttpStatusCode.NoContent) { repository.cancelReservation(gym, occurrence, user); Unit } }
    }
}
private suspend fun io.ktor.server.application.ApplicationCall.gymId(): Long? = parameters["gymId"]?.toLongOrNull() ?: run { respond(HttpStatusCode.BadRequest); null }
private suspend fun io.ktor.server.application.ApplicationCall.id(name: String): Long? = parameters[name]?.toLongOrNull() ?: run { respond(HttpStatusCode.BadRequest); null }
private suspend fun io.ktor.server.application.ApplicationCall.activityResult(status: HttpStatusCode = HttpStatusCode.OK, block: suspend () -> Any) { try { respond(status, block()) } catch (_: DomainNotFoundException) { respond(HttpStatusCode.NotFound) } catch (_: DomainConflictException) { respond(HttpStatusCode.Conflict) } catch (_: IllegalArgumentException) { respond(HttpStatusCode.BadRequest) } }
